\begin{slogan}
Smooth morphisms are locally standard smooth.
\end{slogan}

\begin{slogan}
Smoothness is preserved under base change
\end{slogan}

\begin{slogan}
A ring map is smooth if and only if it is smooth at all primes of the target
\end{slogan}

\begin{slogan}
Smooth schemes are \'etale-locally like affine spaces.
\end{slogan}

\begin{slogan}
Bare-hands construction of fiber products: an affine open cover of a
fiber product of schemes can be assembled from compatible
affine open covers of the pieces.
\end{slogan}

